"use client";
import { useState, type ComponentProps, type CSSProperties, type KeyboardEvent } from "react";
import { cn } from "./lib/cn";
import "./bead-counter.css";

export type BeadCounterProps = Omit<ComponentProps<"div">, "children" | "onChange" | "defaultValue"> & {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** Beads on the wire, 2 to 20. */
  max?: number;
  /** Names the count, e.g. "Guests". */
  label?: string;
};

/**
 * A counter that works like an abacus wire. Beads sit at the left; the count is how many have been slid to the
 * right, from the right-hand end. Press a bead on the left to slide it and every bead after it across; press a bead
 * on the right to slide it and the beads before it back. They clack over one after another, nearest the gap first.
 * The wire is a slider: arrow keys change the count by one, Home and End go to the ends. Under reduced motion the
 * beads move together without easing.
 */
export function BeadCounter({ value, defaultValue = 0, onValueChange, max = 8, label = "Count", className, style, ...props }: BeadCounterProps) {
  const [inner, setInner] = useState(defaultValue);
  const total = Math.max(2, Math.min(20, Math.round(max)));
  const current = Math.max(0, Math.min(total, value ?? inner));
  const set = (next: number) => {
    const clamped = Math.max(0, Math.min(total, next));
    if (value === undefined) setInner(clamped);
    if (clamped !== current) onValueChange?.(clamped);
  };
  const key = (event: KeyboardEvent<HTMLDivElement>) => {
    const next = { ArrowRight: current + 1, ArrowUp: current + 1, ArrowLeft: current - 1, ArrowDown: current - 1, Home: 0, End: total }[event.key];
    if (next === undefined) return;
    event.preventDefault();
    set(next);
  };

  return (
    <div
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={total}
      aria-valuenow={current}
      data-slot="bead-counter"
      className={cn("grid gap-2", className)}
      style={{ "--bdc-n": total, ...style } as CSSProperties}
      onKeyDown={key}
      {...props}
    >
      <span data-slot="bdc-wire">
        {Array.from({ length: total }, (_, index) => (
          <i
            key={index}
            data-slot="bdc-bead"
            data-slid={index >= total - current ? "" : undefined}
            style={{ "--bdc-delay": `${Math.abs(index - (total - current)) * 28}ms` } as CSSProperties}
            onClick={() => set(index < total - current ? total - index : total - index - 1)}
          />
        ))}
      </span>
      <span data-slot="bdc-read" aria-hidden="true">
        {current} of {total}
      </span>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* bead-counter.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Bead counter: slid beads travel one gap to the right, nearest to the boundary first. */
  [data-slot="bead-counter"] { --bdc-w: 28px; --bdc-gap: 56px; width: fit-content; max-width: 100%; color: var(--foreground); font-size: 13px; outline: none; }
  [data-slot="bead-counter"]:focus-visible [data-slot="bdc-wire"] { outline: 2px solid var(--ring); outline-offset: 4px; }
  [data-slot="bead-counter"] [data-slot="bdc-wire"] { position: relative; display: flex; align-items: center; width: calc(var(--bdc-n) * var(--bdc-w) + var(--bdc-gap)); height: 40px; border-radius: 12px; }
  [data-slot="bead-counter"] [data-slot="bdc-wire"]::before { content: ""; position: absolute; inset: 50% 0 auto; height: 2px; margin-top: -1px; border-radius: 1px; background: var(--border-strong); }
  [data-slot="bead-counter"] [data-slot="bdc-bead"] { position: relative; flex: none; width: var(--bdc-w); height: 28px; border: 1.5px solid var(--border-strong); border-radius: 50%; background: color-mix(in oklab, var(--foreground) 10%, var(--background)); cursor: pointer; transition: translate 380ms var(--ease-settle) var(--bdc-delay), background-color var(--duration-normal) var(--ease-out) var(--bdc-delay); }
  [data-slot="bead-counter"] [data-slot="bdc-bead"]::after { content: ""; position: absolute; inset: -8px -2px; }
  [data-slot="bead-counter"] [data-slot="bdc-bead"][data-slid] { translate: var(--bdc-gap) 0; border-color: var(--foreground); background: var(--foreground); }
  [data-slot="bead-counter"] [data-slot="bdc-read"] { color: var(--muted-foreground); font-variant-numeric: tabular-nums; }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="bead-counter"] [data-slot="bdc-bead"] { transition: none; }
  }
}
